import{j as s}from"./visuals-Ce7GuSSc.js";import{CoachPage as i}from"./AnalyzeCoach-BXvOHvcY.js";import"./icons-CCIdVrYy.js";import"./index-DVuunuue.js";import"./solvedBank-BJYOeF2o.js";import"./MathMD-CJeNp8tb.js";import"./Markdown-DzOaLIaB.js";import"./SolvedBank-BkKzzefJ.js";import"./MinitabFigure-Dv3p2-NV.js";const t=[2.1,2.4,2.6,2.8,2.9,3,3.1,3.2,3.3,3.4,3.5,3.6,3.7,3.8,3.9,4.1,4.3,4.5,4.8,5,5.3,5.6,6,6.5,7.2,8,9.1,10.4,12,14.5],o=[48.2,51.6,49.9,47.1,50.8,52.9,49.3,50.1,46.4,51.2,50.5,48.8,53.7,49.6,50.3,47.9,51.9,50,48.5,52.3,49.1,50.7,45.8,51.4,49.8,50.9,48,54.2,50.2,49.4],r=[3.1,3.4,3.6,3.8,3.9,4,4.1,4.2,4.4,4.5,4.7,4.9],n=[4.6,5,5.2,5.4,5.5,5.6,5.8,5.9,6.1,6.3,6.6,9.8],l=[3,3.5,3.9,4.3,4.8,5.2,5.6,6,6.4,6.9,7.3,7.8],c=[{topic:"2.1.1",title:"Cause & Effect / Fishbone Diagrams",oneLine:"A fishbone diagram is a team picture of all the possible causes (X's) of one problem (Y); it collects ideas, it does not rank or prove them.",explain:["A **fishbone diagram** lists **all the possible causes** of one problem. It has three names that mean the same thing: fishbone, **cause and effect diagram**, and **Ishikawa diagram**.",`The **head** of the fish is the **effect**: the problem (Y) from your problem statement, for example "repeat calls about billing". The **bones** are **categories of causes**. The small bones on each big bone are the detailed causes (the X's).`,"Why use it? Remember **Y = f(X)**: to fix a Y you must first find the X's that might drive it. The fishbone is one of the **three sources of X's**: process mapping, fishbone analysis, and basic data analysis.",'How to build it: write the effect in the head. Draw the main bones, often the **6Ms**: Man (People), Machine, Method, Material, Measurement, Mother Nature (Environment). Then the team brainstorms causes on each bone, and asks "why?" again and again (the **5 Whys**) to go deeper.',"Then classify each cause: **C = Controllable** (you can adjust it while the process runs), **P = Procedural** (set by a standard procedure), **N = Noise** (hard, costly or unknown to control). Controllable X's go to the **X-Y matrix**; procedural and noise X's go to the **FMEA**. The fishbone is organised brainstorming, **not data**: Analyze must confirm the causes."],example:`**Repeat billing calls at a contact centre.** The team writes **"Repeat billing calls"** in the head and walks the process map from "customer calls" to "case closed".

| Bone | Cause found | Class |
|---|---|---|
| Machine | CRM screen times out during long calls | C |
| Method | No script for explaining pro-rated charges | P |
| People | New agents not trained on the new tariff | P |
| Material | Bill layout is confusing | C |
| Measurement | Repeat-call flag not set for some cases | P |
| Mother Nature | Peak volume after bills are sent on the 1st | N |

**Next:** the controllable X's (CRM timeout, bill layout) go to the **X-Y matrix** to be ranked. The procedural ones (script, training, flag) and the noise one (peak volume) go to the **FMEA**. Then the team collects data to test the top X's.`,readIt:["Head = the **effect** (one Y). Bones = **categories**. Small bones = **causes** (X's).","If a question asks which tool **generates ideas about possible causes**, the answer is the fishbone.","If it asks which tool **ranks** causes, the answer is the X-Y matrix, not the fishbone.","C (controllable) → X-Y matrix. P (procedural) and N (noise) → FMEA."],remember:["Fishbone = cause and effect diagram = Ishikawa diagram.","Head = effect (Y); bones = categories of causes (X's).","6Ms: Man, Machine, Method, Material, Measurement, Mother Nature.","Classify causes as Controllable, Procedural or Noise.","Three sources of X's: process map, fishbone, basic data analysis.","It is team brainstorming, not proof."],traps:["The fishbone does not rank or prove causes; ranking is the X-Y matrix, proof comes from data in Analyze.",'"Measurement" is one of the 6M cause categories; it is not the effect.',"Temperature or speed = controllable; an SOP = procedural; humidity or ambient conditions = noise."],video:[{kind:"title",say:"The fishbone diagram. A team picture of every possible cause of one problem. It is one of the first Measure tools for finding the X's.",title:"Fishbone Diagram",sub:"Also called cause and effect, or Ishikawa"},{kind:"bullets",say:"The head of the fish is the effect. That is your problem, the Y. Each big bone is a category of causes. A common set is the six M's: man, machine, method, material, measurement and mother nature. The small bones are the detailed causes, the X's.",title:"Head, bones, causes",bullets:["Head = effect (the problem, Y)","Big bones = categories, e.g. the 6Ms","Small bones = causes (X's)",'Ask "why?" to go deeper (5 Whys)']},{kind:"steps",say:"To build one, write the effect in the head. Draw the main bones. Brainstorm causes with the team, walking the process map step by step. Then label each cause as controllable, procedural or noise.",title:"How to build it",steps:["Write one clear effect in the head","Draw the category bones (6Ms)","Team brainstorms causes per bone","Label each cause C, P or N"]},{kind:"compare",say:"The labels decide where each cause goes next. Controllable causes go to the X Y matrix to be ranked. Procedural and noise causes go to the F M E A, to manage their risk.",title:"Where causes go next",left:{head:"Controllable (C)",points:["Can be adjusted while running","e.g. system timeout, bill layout","Next: X-Y matrix"]},right:{head:"Procedural (P) / Noise (N)",points:["SOPs, scripts / peak volume","Hard or costly to control","Next: FMEA"]}},{kind:"callout",say:"Remember. The fishbone collects possible causes. It does not rank them and it does not prove them. Data in Analyze does that.",big:"Fishbone = ideas, not proof",small:"Ranking = X-Y matrix · Proof = Analyze data"}]},{topic:"2.1.2",title:"Process Mapping, SIPOC, Value Stream Map",oneLine:"A process map is a picture of the steps that turn inputs into outputs; SIPOC gives the high-level view with suppliers and customers, and a value stream map adds time and queue data to find bottlenecks.",explain:["A **process map** (flowchart) is a picture of the steps and decisions that turn inputs into an output. Mapping is **the first activity of the Measure phase**. It shows the inputs (X's), outputs (Y's), value-added and non-value-added steps, and where to collect data.","There are **three views** of a process: what you **think** it is, what it **actually** is, and what it **should** be. You find the actual view by **walking the process** with the team. The real process is almost always bigger and messier than people think.","Symbols: **rectangle** = activity (starts with a verb), **diamond** = decision (only Yes or No), **ellipse** = start or end, **parallelogram** = data, **arrow** = flow. Three levels: **Level 1 macro** (management view, about 4–8 steps), **Level 2** (worker view with decisions), **Level 3 micro** (improvement view with performance data such as cycle time and yield).","Four map types: **linear flow**; **swim lane** (one lane per person or team, shows **who** does each step and the hand-offs, where queues form); **SIPOC** = Suppliers, Inputs, Process, Outputs, Customers (high level, built **starting from Outputs and Customers**); and the **value stream map**, which adds speed, queues and data to **find bottlenecks**.",'To test each step ask two questions: does it change the **form, fit or function** of the work? Will the **customer pay** for it? If not, it is **non-value-added (NVA)**. Steps starting with "re" (rework, review, re-enter) are usually waste. Some NVA steps (for example, regulation) must stay, but keep them small.'],example:`**New fibre installation order.** The team builds a **SIPOC** for the order process, in the preferred order:

1. **Outputs:** booked installation, confirmation SMS
2. **Customers:** the home customer, the field technician
3. **Customer requirements:** booking confirmed in under 24 h
4. **Inputs:** address, chosen package, ID document
5. **Suppliers:** customer, sales channel, address database
6. **Input requirements:** address must match the network database

**Process (P):** Receive order → Check coverage → Credit check → Book slot → Confirm. Five steps, so it stays high level.

On the **swim lane map**, the order crosses from Sales to Credit to Scheduling: three hand-offs, and the longest queue sits at Credit. The step "re-enter address in scheduling tool" is **NVA** and is marked with a red X.`,readIt:["Need to see **who** does each step and the hand-offs → **swim lane** map.","Need a **high-level** view with suppliers and customers (4–8 steps) → **SIPOC**.","Need **cycle times, queues and bottlenecks** → **value stream map**.","For each step ask: form/fit/function changed? customer pays? If no → **NVA**."],remember:["Process mapping is the first activity of Measure.","Three views: what you think, what it actually is, what it should be.","Diamond = decision (Yes/No); rectangle = activity; ellipse = start/end.","SIPOC build order: Outputs → Customers → Requirements → Inputs → Suppliers.","Swim lane = who + hand-offs; VSM = speed, queues, bottlenecks.","VA test: form, fit or function changed, and customer willing to pay."],traps:["SIPOC is high level (about 4–8 steps); it does not show detailed decisions.","Review, rework and inspection steps are non-value-added even when they are required.","SIPOC is built from the customer side first (Outputs, Customers), not from Suppliers."],video:[{kind:"title",say:"Process mapping, sigh pock, and the value stream map. Three ways to draw how work really flows.",title:"Process Maps",sub:"Flowchart · SIPOC · Value stream map"},{kind:"bullets",say:"A process map is a picture of the steps. A rectangle is an activity. A diamond is a decision with only yes or no. An ellipse is the start or end. Mapping is the first activity of the Measure phase, and you check it by walking the process.",title:"The basics",bullets:["Rectangle = activity (verb first)","Diamond = decision: Yes or No only","Ellipse = start / end","Walk the process: think vs actual"]},{kind:"steps",say:"S I P O C means suppliers, inputs, process, outputs and customers. Build it from the customer side. First outputs, then customers and their requirements, then inputs, then suppliers. Keep the process to about four to eight steps.",title:"SIPOC build order",steps:["Outputs","Customers + their requirements","Inputs + input requirements","Suppliers","Process: 4–8 high-level steps"]},{kind:"figure",say:"A value stream map adds time and queue data. Here, days of work waiting in front of each step of a fibre order. Credit check holds about six days of work. That is the bottleneck to attack first.",title:"Value stream: find the queue",figure:{kind:"bars",title:"Days of Work Waiting per Step",categories:["Receive","Coverage","Credit","Book slot","Confirm"],series:[{name:"Days in queue",values:[.4,1.1,6.2,2,.3]}],yLabel:"Days"},callouts:["Credit check: 6.2 days waiting","Biggest queue = bottleneck","VSM shows speed, queues, data"]},{kind:"decision",say:"For every step, ask. Does it change the form, fit or function, and would the customer pay for it? If yes, it adds value. If no, it is waste. Steps like rework or re enter are almost always waste.",title:"Value-added or not?",question:"Changes form, fit or function AND customer pays?",yes:"Value-added: keep",no:"Non-value-added: remove or shrink"},{kind:"callout",say:"Remember. Swim lane shows who and the hand offs. Sigh pock is the high level view. The value stream map finds the bottleneck.",big:"Swim lane = who · SIPOC = big picture · VSM = bottleneck"}]},{topic:"2.1.3",title:"X-Y Diagram",oneLine:"The X-Y matrix is a team scoring sheet that ranks the possible X's by how strongly they affect the weighted Y's, so you study the vital few first.",explain:["The **X-Y diagram** (also **X-Y matrix** or **cause and effect matrix**) is a team tool that **ranks the possible X's**. It turns a long list of causes into a short list of the **vital few** to study first.",`It is based on the **team's opinion** ("tribal knowledge"), **not real data**. It is created for **every project** and is **never finished**: you update it whenever a metric, weight or X changes.`,"How to fill it: list the **X's in rows** (the controllable X's from the fishbone). List the **Y's in columns** (primary and secondary metrics). Give each Y a **weight from 1 to 10** (10 = most important). Score each X against each Y on **0, 1, 3 or 9** (none, weak, moderate, strong).",`For each X, multiply each score by that Y's weight and **add across the row**. That sum is the X's **ranking**. Sort from high to low. The wide 1-3-9 gaps stop arguments like "is it a 6 or a 7?" and make strong X's stand out.`,"Then focus **data collection** on the top X's, and feed them into the **FMEA**. The Analyze phase tests them with data, and some surprises are normal."],example:`**Contact centre with two Y's:** customer wait time (weight 10) and first-call resolution (weight 6).

| X | Wait time (w = 10) | Resolution (w = 6) | Ranking |
|---|---|---|---|
| Staffing level | 9 | 3 | 9×10 + 3×6 = **108** |
| Agent training | 3 | 9 | 3×10 + 9×6 = **84** |
| Office lighting | 1 | 1 | 1×10 + 1×6 = **16** |

Total = 108 + 84 + 16 = 208. Staffing level's share is

$$\\text{Rank \\%} = \\dfrac{108}{208} \\times 100 = 51.9\\%$$

**Decision:** collect data on staffing and training first; drop lighting as an obvious low-impact X.`,readIt:["Check the scales: **Y weights 1–10**, **X scores 0, 1, 3, 9**.","Ranking of an X = sum of (score × Y weight) across its row.","The highest ranking = the X to study first. Low rankings can be dropped.","A high ranking is still **opinion**: it tells you where to collect data, not what is proven."],remember:["X-Y matrix = team prioritisation of X's against weighted Y's.","Weights 1–10; scores 0, 1, 3, 9.","Ranking = Σ (score × weight) across the row.","Based on team opinion, not data; never finished.","Controllable X's from the fishbone go in; P and N go to the FMEA."],traps:["The X-Y matrix does not prove causation; it only prioritises data collection.","Do not mix the scales: weights are 1–10, scores are 0/1/3/9.","Multiply score by weight and add across the row; do not just add the scores."],video:[{kind:"title",say:"The X Y diagram. A simple team scoring sheet that ranks your possible causes, so you study the vital few first.",title:"X-Y Diagram",sub:"Also called the cause and effect matrix"},{kind:"steps",say:"List the X's in rows and the Y's in columns. Weight each Y from one to ten. Score each X against each Y with zero, one, three or nine. Then multiply each score by its weight and add across the row.",title:"How to fill it",steps:["X's in rows, Y's in columns","Weight each Y: 1 to 10","Score each X: 0, 1, 3 or 9","Ranking = sum of score × weight"]},{kind:"figure",say:"Here is a contact centre example. Staffing level scores nine on wait time and three on resolution, so its ranking is one hundred and eight. Training gets eighty four. Lighting gets only sixteen. Study staffing and training first.",title:"Rank the X's",figure:{kind:"bars",title:"X-Y Matrix Ranking",categories:["Staffing level","Agent training","Office lighting"],series:[{name:"Ranking",values:[108,84,16]}],yLabel:"Ranking"},callouts:["Staffing: 9×10 + 3×6 = 108","Training: 3×10 + 9×6 = 84","Lighting: 16 → drop it"]},{kind:"compare",say:"Be clear about what the matrix is. It is team opinion that tells you where to look. It is not data, and it does not prove any cause.",title:"What it is, what it is not",left:{head:"It is",points:["Team prioritisation","Updated when things change","A guide for data collection"]},right:{head:"It is not",points:["Real data","Proof of cause","Ever finished"]}},{kind:"callout",say:"Remember. Weights go from one to ten. Scores are zero, one, three or nine. Multiply and add across the row.",big:"Weights 1–10 · Scores 0/1/3/9",small:"Ranking = Σ score × weight"}]},{topic:"2.1.4",title:"Failure Modes & Effects Analysis (FMEA)",oneLine:"FMEA lists how each process step can fail, scores Severity, Occurrence and Detection from 1 to 10, and multiplies them into an RPN to decide which risks to act on first.",explain:["**FMEA** (Failure Modes and Effects Analysis) is a structured team method to **predict how a process can fail** and prevent it. It is about **risk and prevention**, not fixing a problem after it happens. It is a **living document**, re-scored after every action.",'Each row has: the **process step**, the **failure mode** (how it fails, "a fancy name for a defect"), the **effect** (what the customer or next step feels), the **cause** (the X, often from the fishbone) and the **current controls** (for example SPC, mistake-proofing, inspection).',"Then the team scores three things from **1 to 10**. **Severity (S)**: how bad is the effect? 10 = hazardous. **Occurrence (O)**: how often will the cause happen? 10 = very often. **Detection (D)**: how well will current controls catch it? Careful: **10 = almost impossible to detect**, 1 = almost certain to catch it.","Multiply: **RPN = S × O × D**. The Risk Priority Number runs from **1 to 1,000**. Work from the highest RPN down. But also act on any failure with **severity 9 or 10**, even if its RPN is low.","Actions usually lower **Occurrence** (prevent the cause) or lower **Detection** (better controls). **Severity usually stays the same** unless the design changes. After the action, re-score and recalculate the RPN."],example:`**Mobile number port-in process.**

| Failure mode | S | O | D | RPN |
|---|---|---|---|---|
| Wrong address on the order | 7 | 5 | 6 | **210** |
| Wrong tariff applied | 4 | 6 | 3 | **72** |
| Port request lost (customer has no service) | 9 | 2 | 3 | **54** |

Rank by RPN: the address problem is first. The team adds a mistake-proofing check (the system matches the address to the postcode). Re-score: O falls to 3 and D to 2, so the new RPN is 7 × 3 × 2 = **42**.

But "port request lost" has **severity 9**: the customer is left with no service. Even with the lowest RPN, it also gets an action.`,readIt:["Compute **RPN = S × O × D** for each row, then rank from highest to lowest.","Check severity separately: **S = 9 or 10 → act**, whatever the RPN.","Detection is reversed: **high D = poor detection**. D = 10 means you cannot catch it.","After an action, expect **O or D** to fall, not S."],remember:["RPN = Severity × Occurrence × Detection; each 1–10, so RPN is 1–1,000.","Failure mode = defect; effect = what is felt; cause = the X.","Detection 10 = almost impossible to detect; Detection 1 = almost certain.","Act on severity 9–10 regardless of RPN.","FMEA is a living document: re-score after actions.","Order: process map → fishbone → X-Y matrix → FMEA."],traps:["Detection 10 is the worst score (cannot detect), not the best.","Multiply S, O and D; never add them.","Two rows can have the same RPN but very different risk; high severity comes first.","Better controls lower D and prevention lowers O; severity rarely changes."],video:[{kind:"title",say:"F M E A. Failure modes and effects analysis. A way to rank risks before they hurt the customer.",title:"FMEA",sub:"Failure Modes & Effects Analysis"},{kind:"bullets",say:"For each step, the team scores three things from one to ten. Severity, how bad the effect is. Occurrence, how often the cause happens. Detection, how well we catch it. Careful, a detection of ten means we almost cannot detect it.",title:"Three scores, 1 to 10",bullets:["Severity: how bad? 10 = hazardous","Occurrence: how often? 10 = very often","Detection: 10 = cannot detect","RPN = S × O × D (1 to 1,000)"]},{kind:"figure",say:"Here are three port in failures. Wrong address has an R P N of two hundred and ten, so it is first. Wrong tariff is seventy two. Lost port request is only fifty four, but its severity is nine. The customer has no service, so it gets an action too.",title:"Rank by RPN",figure:{kind:"bars",title:"RPN by Failure Mode",categories:["Wrong address","Wrong tariff","Port lost (S=9)"],series:[{name:"RPN",values:[210,72,54]}],yLabel:"RPN"},callouts:["7 × 5 × 6 = 210 → act first","4 × 6 × 3 = 72","S = 9: act even at RPN 54"]},{kind:"decision",say:"So, before you look at the R P N, ask. Is the severity nine or ten? If yes, act anyway. If no, work down the list from the highest R P N.",title:"What to act on",question:"Is severity 9 or 10?",yes:"Act now, whatever the RPN",no:"Work down from the highest RPN"},{kind:"callout",say:"Remember. R P N is severity times occurrence times detection. Actions lower occurrence or detection. Severity usually stays the same.",big:"RPN = S × O × D",small:"Detection 10 = cannot detect · Severity 9–10 = act"}]},{topic:"2.2.1",title:"Basic Statistics",oneLine:"Basic statistics sets the language: a sample describes a population, data is continuous or discrete, and the scale (nominal, ordinal, interval, ratio) decides which tools you may use.",explain:['Statistics turns raw data into information for decisions. The book compares data to **crude oil**: useful only after it is refined. The goal is to decide on **data**, not on "I think" or "I feel".',"A **population** is all the items of interest (for example, every call in 2025). A **sample** is a smaller group taken from it to make an **inference** about the whole. The **frame** is the list you draw the sample from. Numbers that describe a population are **parameters** (Greek letters: μ, σ). Numbers from a sample are **statistics** (Latin letters: x̄, s). We sample because it saves time and money.",'Data types: **continuous** data is measured on a scale and can be split into decimals (call time 4.37 min, download speed 48.2 Mbps). **Discrete** data is counted in whole numbers (number of dropped calls). **Attribute** data has categories such as pass/fail or yes/no. Quick test: does "2.5 of it" make sense?','Scales of measurement, from least to most information, spell **NOIR**: **Nominal** (names only, no order: region, handset brand), **Ordinal** (ordered, gaps not equal: poor / good / excellent, a 1–5 rating), **Interval** (equal gaps, **no true zero**: temperature in °C), **Ratio** (true zero, you can say "twice as much": call time, revenue).',"**Continuous data is always preferred.** It needs smaller samples and allows more powerful tools. Convert counts to rates when you can, for example 200 defects in 8 hours becomes $$\\dfrac{200}{8} = 25$$ defects per hour."],example:`**Classify data from a contact-centre report:**

| Data | Type | Scale |
|---|---|---|
| Average handling time (min) | Continuous | Ratio |
| Number of abandoned calls | Discrete (count) | Ratio |
| Call resolved? Yes/No | Attribute | Nominal |
| Customer satisfaction 1–5 | Discrete | **Ordinal** |
| Region (North, South, Muscat) | Attribute | Nominal |

The team wants to compare shifts of different lengths. Instead of "number of late tickets", they use **minutes late per ticket**: a continuous measure that shows *how* late each ticket was.`,readIt:["Greek letter (μ, σ, N) → **population parameter**. Latin letter (x̄, s, n) → **sample statistic**.","Measured and can be split into decimals → **continuous**. Counted or classified → **discrete / attribute**.","Survey ratings (1–5, poor to excellent) → **ordinal**.",'Has a true zero and "twice as much" makes sense → **ratio**.'],remember:["Population → parameters (μ, σ); sample → statistics (x̄, s).","Continuous = measured; discrete = counted; attribute = categories.","NOIR: Nominal, Ordinal, Interval, Ratio (least to most information).","Only ratio data has a true zero.","Continuous data is preferred; convert counts to rates."],traps:["A 1–5 satisfaction rating is ordinal, not interval or ratio.",'Temperature in °C is interval: 20°C is not "twice as hot" as 10°C.',"x̄ and s describe a sample; μ and σ describe the population."],video:[{kind:"title",say:"Basic statistics. The words you need before any graph or test. The data type you choose decides which tools you can use later.",title:"Basic Statistics",sub:"Population, sample, data types, scales"},{kind:"compare",say:"A population is every item. A sample is a small part of it that we use to make an inference. Population numbers are parameters with Greek letters, mu and sigma. Sample numbers are statistics, x bar and s.",title:"Population vs sample",left:{head:"Population",points:["All items of interest","Parameters: μ, σ, N","Usually too costly to measure"]},right:{head:"Sample",points:["A smaller subset","Statistics: x̄, s, n","Used to make an inference"]}},{kind:"decision",say:"To find the data type, ask. Is it measured on a scale, where decimals make sense? If yes, it is continuous, like call time. If no, it is discrete or attribute, like the number of dropped calls, or pass and fail.",title:"Which data type?",question:"Measured on a scale, decimals make sense?",yes:"Continuous (time, speed, money)",no:"Discrete / attribute (counts, pass-fail)"},{kind:"steps",say:"The four scales spell noir. Nominal is names only. Ordinal has order, like a one to five rating. Interval has equal gaps but no true zero, like degrees Celsius. Ratio has a true zero, like call time.",title:"Scales: NOIR",steps:["Nominal: names only (region)","Ordinal: ordered (1–5 rating)","Interval: equal gaps, no true zero (°C)","Ratio: true zero (call time)"]},{kind:"callout",say:"Remember. Continuous data is always preferred. If you only have counts, turn them into a rate, like defects per hour.",big:"Continuous data is preferred",small:"Convert counts to rates when you can"}]},{topic:"2.2.2",title:"Descriptive Statistics",oneLine:"Descriptive statistics summarise data with its centre (mean, median, mode) and its spread (range, IQR, standard deviation, variance); the gap between mean and median tells you about skew.",explain:["**Descriptive statistics** summarise a data set with a few numbers. There are two families: **location** (where the centre is) and **variation** (how spread out the data is).","**Location:** the **mean** is the average, the balance point. The **median** is the middle value after sorting; it is **not pulled by extreme values**. The **mode** is the most frequent value; two modes (**bimodal**) often means two processes are mixed.",'**Variation:** the **range** = largest − smallest. The **IQR** (interquartile range) = Q3 − Q1, the spread of the middle 50%. The **variance** is the average squared distance from the mean. The **standard deviation (SD)** is its square root, a "typical distance" from the mean. For a **sample**, divide by **n − 1**:',"$$s = \\sqrt{\\dfrac{\\sum (x - \\bar{x})^2}{n - 1}}$$ For a whole population you divide by N. **Variances can be added; standard deviations cannot.** Two independent steps with SD 3 and SD 4 give a total SD of 5, not 7.","How to decide: if the **mean is much bigger than the median**, a few large values pull it up: the data are **right-skewed**. For skewed data report **median and IQR**. For symmetric data report **mean and SD**."],example:`**Five call-handling times (min): 4, 6, 5, 9, 6.**

- Mean = 30 ÷ 5 = **6**. Sorted: 4, 5, 6, 6, 9 → median **6**, mode **6**, range 9 − 4 = **5**.
- Deviations from 6: −2, 0, −1, 3, 0. Squares: 4, 0, 1, 9, 0. Sum = **14**.
- Sample variance and SD:

$$s^2 = \\dfrac{14}{5 - 1} = 3.5 \\qquad s = \\sqrt{3.5} = 1.87$$

- If these five were the **whole population**: σ² = 14 ÷ 5 = 2.8, σ = 1.67.

**Skew check on 30 calls:** mean 5.15 min, median 4.00 min. The mean is above the median, so a few long calls pull it up: **right skew**. Report the median and IQR (3.18 to 6.13 min).`,readIt:['Minitab "Display Descriptive Statistics" shows N, Mean, SE Mean, StDev, Minimum, Q1, Median, Q3, Maximum.',"**Mean > median** → right skew (long tail to the right). Mean < median → left skew.","IQR = Q3 − Q1. Range = Maximum − Minimum.",'Sample data → SD with **n − 1**. Check the question: "sample" or "population"?'],remember:["Location: mean, median, mode. Variation: range, IQR, SD, variance.","The median resists outliers; the mean does not.","Sample SD divides by n − 1; population SD divides by N.","SD = square root of variance.","Variances add; standard deviations do not.","Symmetric → mean + SD; skewed → median + IQR."],traps:["Sample SD divides by n − 1, not n.","Never add two SDs directly: square, add, then take the square root.","Mean > median means right skew, not left."],video:[{kind:"title",say:"Descriptive statistics. A few numbers that tell you the centre and the spread of your data. Every Measure phase reports them for the Y.",title:"Descriptive Statistics",sub:"Centre and spread"},{kind:"compare",say:"There are two families. Location tells you where the centre is, the mean, median and mode. Variation tells you how spread out the data are, the range, the interquartile range, the variance and the standard deviation.",title:"Two families",left:{head:"Location (centre)",points:["Mean = average","Median = middle value","Mode = most frequent"]},right:{head:"Variation (spread)",points:["Range = max − min","IQR = Q3 − Q1","SD = √variance"]}},{kind:"figure",say:"Here are thirty call handling times. Most calls are short, but a few long calls make a tail to the right. The mean is five point one five minutes, but the median is only four. Mean above median means right skew.",title:"Mean vs median",figure:{kind:"histogram",title:"Histogram of Handling Time",data:t,bins:8,xLabel:"Handling time (min)",stats:[["N","30"],["Mean","5.153"],["StDev","2.987"],["Q1","3.175"],["Median","4.000"],["Q3","6.125"]]},callouts:["Mean 5.15 > median 4.00","Long tail to the right = right skew","Report median and IQR"]},{kind:"decision",say:"So which numbers do you report? Ask, is the data roughly symmetric? If yes, use the mean and the standard deviation. If no, use the median and the interquartile range.",title:"Which summary?",question:"Is the data roughly symmetric?",yes:"Report mean + standard deviation",no:"Report median + IQR"},{kind:"callout",say:"Remember. For a sample, the standard deviation divides by n minus one. And variances add, standard deviations do not.",big:"Sample SD: divide by n − 1",small:"Variances add · SDs do not"}]},{topic:"2.2.3",title:"Normal Distributions & Normality",oneLine:"The normal curve is a symmetric bell set by its mean and SD; check normality with the Anderson-Darling test, where p > 0.05 means you fail to reject normality.",explain:["The **normal distribution** is the smooth, symmetric **bell curve**. Its **mean, median and mode are equal**, at the centre. Two numbers set its shape: the **mean** and the **standard deviation**. It describes a process with only random variation, free of special causes, drifts and shifts.","**Empirical rule:** about **68%** of data lie within ±1 SD of the mean, **95%** within ±2 SD and **99.7%** within ±3 SD. A **Z-score** tells you how many SDs a value is from the mean: $$Z = \\dfrac{x - \\mu}{\\sigma}$$ The area beyond a spec limit is the expected share of defects.","Why check normality? **Many tools assume it** (capability, some tests, control limits). But **many service processes are not normal**. Time cannot go below zero, so call and repair times are usually **right-skewed**. Always check before using a tool that assumes normality.",'How to check: the **Anderson-Darling (AD) test** and the **normal probability plot**. The null hypothesis is **"the data are normal"**. If **p > 0.05**, you **fail to reject** it: treat the data as normal enough. If **p ≤ 0.05**, reject it: the data are **not normal**. On the plot, normal data fall close to a **straight line**.',"If the data are not normal, **do not panic**. Look for special causes, **stratify** (by shift, site, agent) and go and see the process. A **bimodal** shape often means two processes are mixed. Very large samples make the AD test over-sensitive, and a histogram of 20 points cannot judge normality."],example:`**Two data sets from the same team.**

- **Broadband speed tests (30 tests):** mean 50.0 Mbps, SD 1.98. AD = 0.127, **p = 0.982**. The points follow the line. p > 0.05 → **fail to reject** normality: treat as normal.
- **Call handling time (30 calls):** AD = 2.004, **p < 0.005**. The points bend away from the line at the top (a few very long calls). p ≤ 0.05 → **reject**: the data are **not normal** (right-skewed). Next, stratify by call type to look for special causes.

**Z-score check:** mean 50, SD 3, upper spec 54.

$$Z = \\dfrac{54 - 50}{3} = 1.33$$

About **9.2%** of output is above the spec.`,readIt:["Find the **P-Value** in the probability plot legend.","**p > 0.05** → fail to reject H₀ → data can be treated as normal.","**p ≤ 0.05** → reject H₀ → data are **not normal**.","Points on the straight line = normal. Points curving away at one end = skew or outliers."],remember:["Normal curve: symmetric bell; mean = median = mode.","Set by two parameters: mean and standard deviation.","Empirical rule: 68% / 95% / 99.7% within ±1 / 2 / 3 SD.","AD test H₀ = data are normal.","p > 0.05 → fail to reject normality; p ≤ 0.05 → not normal.",'Service and time data are often right-skewed, and that is not "bad".'],traps:['A high AD p-value never "proves" or "accepts" normality; you only fail to reject it.',"A low p-value means NOT normal, because H₀ says the data are normal.","Do not judge normality from a histogram of a small sample; use the AD test and probability plot.","With very large samples, the AD test can flag tiny, harmless departures."],video:[{kind:"title",say:"Normal distributions and normality. How to tell if your data follow the bell curve.",title:"Normality",sub:"Bell curve · Anderson-Darling test"},{kind:"bullets",say:"The normal curve is a symmetric bell. The mean, median and mode are the same. About sixty eight percent of data lie within one standard deviation, ninety five percent within two, and ninety nine point seven percent within three.",title:"The bell curve",bullets:["Symmetric: mean = median = mode","Set by mean and SD","68% / 95% / 99.7% within 1 / 2 / 3 SD","Many tools assume it"]},{kind:"figure",say:"Here is a normal probability plot of thirty broadband speed tests. The points sit close to the straight line. The Anderson Darling p value is zero point nine eight two, well above zero point zero five. So we fail to reject normality.",title:"Points on the line",figure:{kind:"probability",title:"Probability Plot of Speed (Normal)",data:o,xLabel:"Download speed (Mbps)",stats:[["Mean","50.02"],["StDev","1.975"],["N","30"],["AD","0.127"],["P-Value","0.982"]]},callouts:["Points follow the line","p = 0.982 > 0.05","Fail to reject: treat as normal"]},{kind:"figure",say:"Now thirty call handling times. The points curve away from the line at the top, because a few calls are very long. The p value is below zero point zero zero five. We reject normality. The data are right skewed.",title:"Points bend away",figure:{kind:"probability",title:"Probability Plot of Handling Time (Normal)",data:t,xLabel:"Handling time (min)",stats:[["Mean","5.153"],["StDev","2.987"],["N","30"],["AD","2.004"],["P-Value","<0.005"]]},callouts:["Curve at the top = long right tail","p < 0.005 ≤ 0.05","Reject: not normal"]},{kind:"decision",say:"So the rule is simple. Is the p value greater than zero point zero five? If yes, fail to reject, and treat the data as normal. If no, the data are not normal. Look for special causes and stratify.",title:"Normal or not?",question:"Anderson-Darling p-value > 0.05?",yes:"Fail to reject: treat as normal",no:"Not normal: stratify, find causes"},{kind:"callout",say:"Remember. We never prove normality. A high p value only means we fail to reject it.",big:"p > 0.05 → fail to reject normality",small:'Never say "proved normal"'}]},{topic:"2.2.4",title:"Graphical Analysis",oneLine:"Pick the graph for the question: histogram for shape, box plot to compare groups and spot outliers, time series plot for change over time, scatter plot for a link between two variables.",explain:["Graphs let you **see** the data before you calculate anything: the shape, centre, spread, outliers, changes over time and links between variables. Graph the **top X's** from the X-Y matrix, and **stratify** by time, location and operator (agent).","**Histogram:** bars of equal width; bar height = how many values fall in that range. It shows **shape, centre and spread**, and skew. **Dot plot:** one dot per value; good for small samples and shows individual points. Do not judge normality from a histogram of about 20 points.","**Box plot:** the **box runs from Q1 to Q3** (the middle 50%), the **line inside is the median**, and the **whiskers** reach the last values that are not outliers. An **outlier** (asterisk) is more than **1.5 × IQR** beyond the box. Box plots are ideal for **comparing groups** side by side (sites, shifts, before/after). They can hide a bimodal shape, so check an individual value plot too.","**Time series plot:** data **in time order**. Every project should have one, to see trends, cycles and shifts. A histogram cannot show time order. **Scatter plot:** two continuous variables (X across, Y up); it shows **association, not proof of cause**.","How to decide: shape → histogram; compare groups or find outliers → box plot; change over time → time series plot (or control chart); relationship between two variables → scatter plot; which categories cause most defects → Pareto chart."],example:`**Queue wait time at three sites (12 calls each).**

- **Site A:** median 4.05 min, small box. Fast and consistent.
- **Site B:** Q1 5.25, Q3 6.25, so IQR = 1.0. Upper fence = 6.25 + 1.5 × 1.0 = **7.75**. One call waited **9.8 min**, above the fence: an **outlier** (asterisk). Check the log for that day before deciding.
- **Site C:** median 5.40 min, but the **widest box** (Q1 4.0 to Q3 6.775): the most variation.

**Decision:** Site C has a spread problem; Site B has one special event to investigate. A time series plot of each site would show whether the waits change during the day.`,readIt:["Box plot: line in the box = **median**; box = **Q1 to Q3**; asterisk = **outlier** (beyond 1.5 × IQR).","A taller box = more spread in the middle 50%.","Histogram with a long right tail = right skew (mean > median).",'Words like "over time", "trend" or "shift" → time series plot or control chart.'],remember:["Histogram = shape, centre, spread (larger samples).","Box plot: box Q1–Q3, line = median, outlier beyond 1.5 × IQR.","Box plot = best for comparing groups.","Time series plot = changes over time; every project needs one.","Scatter plot = two continuous variables; association, not causation."],traps:["The line inside a box plot is the median, not the mean.","A histogram cannot show a trend, because it loses time order.","A box plot can hide a bimodal distribution; use an individual value plot or dot plot to check.","A scatter plot pattern does not prove that X causes Y."],video:[{kind:"title",say:"Graphical analysis. How to pick the right graph, and how to read it.",title:"Graphical Analysis",sub:"See the data before you calculate"},{kind:"figure",say:"This box plot compares wait times at three sites. The box runs from the first to the third quartile, and the line inside is the median. Site A is fast and tight. Site C has the tallest box, so the most spread. Site B has an asterisk at nine point eight minutes. It is beyond one and a half times the box height, so it is an outlier.",title:"Reading a box plot",figure:{kind:"boxplot",title:"Boxplot of Wait Time by Site",groups:[{name:"Site A",data:r},{name:"Site B",data:n},{name:"Site C",data:l}],yLabel:"Wait time (min)",xLabel:"Site"},callouts:["Line in box = median","Site C: tallest box = most spread","Site B: 9.8 > fence 7.75 = outlier"]},{kind:"steps",say:"Match the graph to the question. For shape and spread, use a histogram. To compare groups or find outliers, use a box plot. For change over time, use a time series plot. For a link between two variables, use a scatter plot.",title:"Which graph?",steps:["Shape and spread → histogram","Compare groups, outliers → box plot","Change over time → time series plot","Two variables linked? → scatter plot"]},{kind:"compare",say:"One common mix up. A histogram shows shape but loses the time order, so it cannot show a trend. A time series plot keeps the order, so it shows trends, cycles and shifts.",title:"Shape vs time",left:{head:"Histogram",points:["Shape, centre, spread","Shows skew","No time order: no trends"]},right:{head:"Time series plot",points:["Data in time order","Trends, cycles, shifts","Every project needs one"]}},{kind:"callout",say:"Remember. In a box plot, the line is the median and an asterisk is an outlier. And a scatter plot shows a link, not proof of cause.",big:"Box plot line = median · * = outlier",small:"Scatter = association, not causation"}]}],d=[60.4,60.9,59.9,58.8,59.6,58.6,60.5,62.7,59.5,59.3],h=[61.7,61.7,61.6,61.4,61.6,61.8,61.3,61.5,61.2,61.3],m=[[30,.18],[30,.37],[30,.25],[60,.73],[60,.72],[60,.68],[90,.7],[90,.94],[90,.99],[120,1.31],[120,1.12],[120,1.24],[150,1.48],[150,1.5],[150,1.73]],p=[6.34,6.94,7.65,6.51,6.88,7.05,7.01,6.01,7.02,8.02,5.76,7.63,7.06,6.47,8.52,7.56,6.03,7.02,7.41,6.82,7.5,6.91,7.48,8.08,6.44,7.12,6.6,7.06,6.04,6.51,6.81,7.66,7.85,5.94,6.35,7.47,5.42,6.6,6.89,7.94,7.5,6.71,6.68,6.77,8.15,6.63,6.73,7.24,6.87,6.81,6.1,6.96,6.62,7.87,7.47,6.95,7.48,6.7,7.78,6.96,7.42,5.96,7.23,5.65,5.38,6.73,6.26,7.09,8.71,6.32,6.48,7.12,7.35,6.83,6.8,7.51,7.37,6.16,6.9,6.99,6.14,7.17,6.3,7.72,7.11,7.03,6.5,6.87,5.41,6.08,7.25,5.31,7.62,5.61,7.55,6.31,7.57,7.07,5.77,7.94],u=[19.5,18.1,17.9,18,17.2,19.2,17.6,18.1,17.4,17.5,16.9,22.8,18,19.1,18.2,17.5,17.8,17.6,18.1,17.8,17.8,16.8,17.4,19.8,17.5],b=[.08,.0575,.075,.07,.0925,.06,.065,.08,.0875,.06,.0875,.1025,.065,.06,.0775,.08,.14,.09,.055,.07,.0875,.08,.0725,.0925,.1125],f=[{topic:"2.3.1",title:"Precision & Accuracy",oneLine:"Accuracy means the measurements are right on average; precision means they repeat with little spread. A good measurement system needs both.",explain:["Before you trust any data, you must check the tool that made it. This check is called **MSA** (Measurement System Analysis). The **measurement system** is everything used to get a number: the gage or software, the method, the people, and the environment. It is not just calibration.",'Why? What you see is **real process variation plus measurement error**. If the measurement error is big, you will chase problems that are not there, or miss real ones. The book calls MSA "non-negotiable": do it **before** capability, hypothesis tests or DOE.',"**Accuracy** is about **location**: is the average of the measurements close to the true (reference) value? Its parts are **bias, linearity and stability**. **Precision** is about **spread**: do repeated readings agree? Its parts are **repeatability** and **reproducibility**.","**Repeatability** = the same person, same tool, same item, measured again and again. It is also called **equipment variation**. **Reproducibility** = different people measuring the same item get different averages. It is also called **appraiser variation**.","Think of a target. Shots tight together but away from the centre = **precise, not accurate** (fix by calibrating). Shots centred but spread wide = **accurate, not precise** (fix the tool or method). Tight and on the centre = good."],example:`**Call-timing tools.** A reference test call lasts exactly **60 seconds**. Two timing tools measure it 10 times each.

| Tool | Average | Standard deviation | Verdict |
|---|---|---|---|
| Timer A | 60.02 s | 1.19 s | Accurate, **not precise** |
| Timer B | 61.51 s | 0.20 s | Precise, **not accurate** (bias about +1.5 s) |

Timer B is easy to fix: **calibrate** it to remove the 1.5-second offset. Timer A is harder: its average is right, but any single reading can be a second or more off, so the team needs a better tool or method.`,readIt:["Compare the **average** with the reference value: a gap means an **accuracy** (bias) problem.","Look at the **spread** (standard deviation) of repeated readings: wide spread means a **precision** problem.","Same person disagrees with themself → **repeatability** (the tool). Different people disagree → **reproducibility** (training, method).","Readings that are **always exactly the same** can mean poor resolution, not a perfect gage."],remember:["MSA first: check the measurement system before analysing data.","Accuracy = average vs true value (location): bias, linearity, stability.","Precision = spread of repeated readings: repeatability, reproducibility.","Repeatability = one person, one tool, repeated (equipment variation).","Reproducibility = differences between people (appraiser variation).","Calibration fixes bias (accuracy), not precision."],traps:["Swapping the terms: repeatability is within one appraiser; reproducibility is between appraisers.","Target pictures: tight but off-centre is precise, NOT accurate.","Thinking MSA is just calibration — it covers people, method and environment too."],video:[{kind:"title",say:"Precision and accuracy. Before you trust any number, check the tool that made it.",title:"Precision & Accuracy",sub:"The first question of M S A"},{kind:"compare",say:"Accuracy is about location. Is the average close to the true value? Precision is about spread. Do repeated readings agree with each other? Accuracy has three parts: bias, linearity and stability. Precision has two: repeatability and reproducibility.",title:"Two different questions",left:{head:"Accuracy (location)",points:["Average vs true value","Bias, linearity, stability","Fix: calibrate"]},right:{head:"Precision (spread)",points:["Do repeats agree?","Repeatability, reproducibility","Fix: tool, method, training"]}},{kind:"figure",say:"Two timing tools measure a sixty second test call ten times each. Timer A is centred on sixty, but its readings spread widely. Accurate, not precise. Timer B is very tight, but it reads about one and a half seconds high. Precise, not accurate. Calibration fixes Timer B.",title:"Two timers, one test call",figure:{kind:"boxplot",title:"Boxplot of Measured Time (true value = 60 s)",groups:[{name:"Timer A",data:d},{name:"Timer B",data:h}],yLabel:"Seconds",refLine:60},callouts:["A: mean 60.02, SD 1.19 → accurate, not precise","B: mean 61.51, SD 0.20 → precise, biased","Bias is easier to fix than spread"]},{kind:"bullets",say:"Precision has two parts. Repeatability is one person, one tool, measuring the same item again and again. It is also called equipment variation. Reproducibility is different people getting different averages on the same item. It is called appraiser variation.",title:"The two parts of precision",bullets:["Repeatability: one person, same item, again","Also called equipment variation","Reproducibility: different people differ","Also called appraiser variation"]},{kind:"callout",say:"Remember. Accuracy is the average. Precision is the spread. And always check the measurement system before you analyse the data.",big:"Accuracy = average · Precision = spread",small:"MSA comes before any analysis"}]},{topic:"2.3.2",title:"Bias, Linearity & Stability",oneLine:"Bias is a fixed offset from the truth, linearity is bias that changes across the range, and stability is bias that changes over time — all three are accuracy problems.",explain:["These three are the parts of **accuracy**. They all move the **average** of the readings, not the spread. To study any of them, you measure a **reference** (a master or standard whose true value is known) and compare.","**Bias** is the gap between the average reading and the true value. A scale that shows 3 kg with nothing on it has a 3 kg bias. **Calibration** reduces bias, but wear and tear means it never goes away completely.","**Linearity** asks: is the bias the **same across the whole range**? Measure references at the low, middle and high end. Plot bias against the reference value. A flat line is good. A sloped line means the bias grows or shrinks with size. The book uses $\\%\\text{Linearity} = |\\text{slope}| \\times 100$.","**Stability** asks: does the bias **change over time** (drift)? Measure the same master item every day or shift and plot it on a **control chart**. The book says a gage stability study should be the first exercise after calibration.",'Key words decide most exam questions: "offset from the true value" = bias; "across the range" = linearity; "over time" = stability. Do not confuse gage stability with **process** stability (topic 2.4.2).'],example:`**Call-duration recorder.** The team plays reference test calls of 30, 60, 90, 120 and 150 seconds, three times each, and records the bias (reading minus true length).

- At 30 s the average bias is about **+0.27 s**; at 150 s it is about **+1.57 s**.
- Fitted line: bias = −0.007 + 0.0104 × reference. The slope is **0.0104**, so %Linearity is about **1%**.

The bias grows with call length: this is a **linearity** problem, not a constant bias. One offset correction will not fix it; the recorder needs repair or calibration across the range. Separately, the team plays a 60 s test call every morning and charts it to watch **stability**.`,readIt:["Bias = average reading − reference value. A non-zero average gap = bias.","Linearity plot (bias vs reference): **flat line** = good; **sloped line** = bias changes across the range.","Stability: control chart of one master item over time; a trend or shift = drift.","Constant offset → calibrate; sloped bias → repair or calibrate across the range; drift → schedule checks and recalibration."],remember:["Bias, linearity, stability = accuracy (location) errors.","Bias = measured average − reference value.","Linearity = bias changes across the operating range.","Stability = bias changes over time (drift); use a control chart.","Calibration controls bias but never removes it fully."],traps:['"Over time" means stability, "across the range" means linearity — read the stem carefully.',"Gage stability (2.3.2) is not process stability (2.4.2).","None of these three affect precision; repeatability and reproducibility do."],video:[{kind:"title",say:"Bias, linearity and stability. The three ways a measurement can be off target.",title:"Bias, Linearity & Stability",sub:"The three parts of accuracy"},{kind:"bullets",say:"All three are accuracy problems. They move the average, not the spread. Bias is a fixed offset from the true value. Linearity is bias that changes across the range. Stability is bias that changes over time.",title:"Three location errors",bullets:["Bias: offset from the true value","Linearity: bias changes across the range","Stability: bias changes over time","All three move the average"]},{kind:"figure",say:"Here a call recorder is tested with reference calls from thirty to one hundred and fifty seconds. The bias is about point three seconds on short calls, and about one point six seconds on long calls. The line slopes up. That is a linearity problem. A flat line would be good.",title:"Linearity: bias vs size",figure:{kind:"scatter",title:"Gage Linearity: Bias vs Reference",points:m,xLabel:"Reference call length (s)",yLabel:"Bias (s)",fit:{b0:-.007,b1:.0104},stats:[["Slope","0.0104"],["%Linearity","1.04"]]},callouts:["Sloped line = linearity problem","Bias ≈ 0.27 s at 30 s, ≈ 1.57 s at 150 s","Flat line at zero = ideal"]},{kind:"decision",say:"To spot stability, measure the same master item every day and put it on a control chart. Does the bias drift over time? If yes, it is a stability problem: recalibrate and check on a schedule. If no, the gage is stable.",title:"Stability check",question:"Does the master reading drift over time?",yes:"Stability problem: recalibrate, check often",no:"Gage is stable over time"},{kind:"callout",say:"Remember the key words. Offset is bias. Across the range is linearity. Over time is stability.",big:"Offset = bias · Range = linearity · Time = stability",small:"All three are accuracy, not precision"}]},{topic:"2.3.3",title:"Gage Repeatability & Reproducibility",oneLine:"A Gage R&R study splits the total variation into measurement error and real part-to-part differences; measurement error should be a small share.",explain:["A **Gage R&R study** tells you how much of your variation comes from the **measurement system** and how much comes from **real differences between items**. Gage R&R = **repeatability** (the tool) + **reproducibility** (the people).","The classic design is **10 parts × 3 operators × 2 or 3 trials**, all **crossed** (every operator measures every part). Pick parts that cover the **whole range** of the process, not random ones. Run it **blind** and in **random order**, and calibrate first.",`Minitab gives four key numbers. **%Contribution** uses variances, so it adds to 100%. **%Study Var** uses standard deviations, so it does **not** add to 100%:

$$\\%\\text{Study Var} = \\dfrac{SD_{R\\&R}}{SD_{total}} \\times 100$$

**%Tolerance** compares measurement error with the spec width. **ndc** (number of distinct categories) says how many groups of parts the system can tell apart.`,"The exam rule for %Study Var or %Tolerance: **below 10% = acceptable**, **10–30% = marginal** (may be OK depending on cost and importance), **above 30% = unacceptable**. For %Contribution the bands are 1% and 9%. You want **ndc ≥ 5**.","Graphs: part-to-part bars should be much **taller** than Gage R&R bars. The **R chart by operator** should be **in control**. The **Xbar chart by operator** should be mostly **out of control**, because the parts were chosen to be different. If repeatability is the bigger part, fix the **gage**; if reproducibility is bigger, **train** the people and standardise the method."],example:`**Book's Minitab output** (10 items, 3 operators, 2 trials):

| Source | %Contribution | %Study Var |
|---|---|---|
| Total Gage R&R | 2.91 | **17.05** |
| Repeatability | 2.11 | 14.54 |
| Reproducibility | 0.79 | 8.91 |
| Part-to-part | 97.09 | 98.54 |

ndc = **8**.

**Decision:** 17% Study Var is in the **10–30% marginal** band, so the system can be used with care. ndc 8 is fine (≥ 5). Repeatability is larger than reproducibility, so improvement should focus on the **equipment**, not the operators. In a contact centre, the same logic applies when several QA analysts time the same recorded calls.`,readIt:["Find **Total Gage R&R** in the %Study Var column: < 10% accept, 10–30% marginal, > 30% reject.","Check **ndc**: 5 or more is good (Minitab rounds it down).","Compare repeatability vs reproducibility: the bigger one tells you what to fix (gage vs people).","Graphs: R chart in control; Xbar chart mostly OUT of control; operator lines flat and parallel."],remember:["Gage R&R = repeatability + reproducibility (as variances).","Classic design: 10 parts × 3 operators × 2–3 trials, crossed, blind, random order.","%Study Var: < 10 good, 10–30 marginal, > 30 bad.","%Contribution adds to 100%; %Study Var does not.","ndc ≥ 5.","Good system: part-to-part is the biggest component."],traps:["An IN-control Xbar chart by operator is bad news: the gage cannot see part differences.","Adding %Study Var values and expecting 100% — only %Contribution adds up.","Choosing random parts: parts must span the full process range.","Destructive test → you cannot use crossed; use a nested design (2.3.4)."],video:[{kind:"title",say:"Gage R and R. How much of what you see is the measurement, and how much is real?",title:"Gage R&R",sub:"Repeatability + Reproducibility"},{kind:"steps",say:"The classic study. Pick ten parts that cover the whole range. Three operators measure every part, two or three times. Do it blind and in random order. Then let Minitab split the variation.",title:"Run the study",steps:["Pick 10 parts across the full range","3 operators measure every part","Repeat 2–3 times, blind, random order","Minitab splits the variation"]},{kind:"figure",say:"Here is the components of variation chart. The part to part bars are tall, which is good. Total Gage R and R is about seventeen percent of study variation. That sits in the marginal band, between ten and thirty. Repeatability is bigger than reproducibility, so look at the gage first.",title:"Components of variation",figure:{kind:"bars",title:"Components of Variation",categories:["Gage R&R","Repeat","Reprod","Part-to-Part"],series:[{name:"% Contribution",values:[2.91,2.11,.79,97.09]},{name:"% Study Var",values:[17.05,14.54,8.91,98.54]}],yLabel:"Percent"},callouts:["Gage R&R = 17% Study Var → marginal","Part-to-part is the biggest bar: good","Repeat > Reprod → fix the gage first"]},{kind:"bullets",say:"Read the numbers like this. Under ten percent study variation is acceptable. Ten to thirty is marginal. Over thirty is unacceptable. The number of distinct categories, n d c, should be five or more. And the X bar chart by operator should be mostly out of control.",title:"How to judge it",bullets:["%Study Var: <10 OK, 10–30 marginal, >30 bad","ndc should be 5 or more","R chart by operator: in control","Xbar chart by operator: mostly OUT"]},{kind:"callout",say:"Remember. Ten and thirty percent are the lines. n d c at least five. Repeatability problem, fix the gage. Reproducibility problem, train the people.",big:"<10% good · 10–30% marginal · >30% bad",small:"ndc ≥ 5 · Repeat → gage · Reprod → people"}]},{topic:"2.3.4",title:"Variable & Attribute MSA",oneLine:"Use Gage R&R for continuous numbers (crossed, or nested for destructive tests) and attribute agreement analysis with kappa when people classify items.",explain:['There are two kinds of MSA. **Variable MSA** (Gage R&R) is for **continuous** numbers, like handle time in seconds. **Attribute MSA** (attribute agreement analysis) is for **categories**, like pass/fail, call reason, or "complaint / not complaint". Variable data is always preferred because it carries more information, but transactional work often only has attribute data.',"Variable MSA has two designs. **Crossed**: every operator measures every part. This is the normal case for non-destructive tests. **Nested**: each part is measured by **only one operator**. You need nested when the test **destroys** the item (a crash test, a burst test), or when parts cannot reach every operator.","Attribute MSA: several appraisers (for example 3 QA evaluators) classify the **same set of items** (often 50) at least twice, **blind** and in random order. Each item needs a **known correct answer** (the standard), set before the study. You need about **5 times** as many samples as a variable study.",`Minitab shows four views: **within appraiser** (do they agree with themselves?), **each appraiser vs standard** (are they correct?), **between appraisers** (do they agree with each other?), and **all appraisers vs standard**. Agreement is a simple percentage:

$$\\%\\text{Agreement} = \\dfrac{\\text{matched}}{\\text{inspected}} \\times 100$$`,"**Kappa** measures agreement **beyond chance**. Kappa 1 = perfect, 0 = no better than chance. **Kappa ≥ 0.70** is usually required; about 0.90 is preferred. If people agree with themselves but not with the standard, the fix is a **clearer operational definition and training**."],example:`**QA call classification.** Three evaluators each classify 15 recorded calls twice as "resolved" or "not resolved"; the correct answer for each call is known.

| Appraiser | Matched standard | Percent |
|---|---|---|
| Appraiser 1 | 8 of 15 | 53.3% |
| Appraiser 2 | 13 of 15 | 86.7% |
| Appraiser 3 | 15 of 15 | 100% |
| All vs standard | 6 of 15 | **40%** |

The book wants "all vs standard" above 75% (many firms aim for 90%). **40% is far too low.** Appraiser 1 needs targeted training, and the definition of "resolved" must be written more clearly. The confidence intervals are wide, so a repeat study should use more calls.`,readIt:["Continuous number → variable Gage R&R; category / pass-fail → attribute agreement.","Destructive test or each part seen by one operator only → **nested**; otherwise crossed.",'Read "each appraiser vs standard" to see who is wrong; read "all vs standard" for the overall verdict.',"Kappa ≥ 0.70 acceptable; < 0.70 → clarify the definition and retrain."],remember:["Variable MSA = Gage R&R; attribute MSA = agreement analysis + kappa.","Crossed = every operator measures every part.","Nested = each part measured by one operator (destructive tests).","Attribute MSA needs a known standard, blind samples, ~5× more samples.","Kappa: 1 perfect, 0 chance; ≥ 0.70 required."],traps:["Destructive testing → NESTED Gage R&R, never crossed.","High within-appraiser agreement does not mean correct — check vs the standard.",'Kappa 0 means "no better than chance", not "zero agreement".'],video:[{kind:"title",say:"Variable and attribute M S A. Which study fits your data?",title:"Variable & Attribute MSA",sub:"Numbers or categories?"},{kind:"compare",say:"If the measurement is a continuous number, use a variable study: Gage R and R. If people put items into categories, like pass or fail, use an attribute agreement study, judged with kappa.",title:"Two kinds of MSA",left:{head:"Variable MSA",points:["Continuous number","Gage R&R","Crossed or nested"]},right:{head:"Attribute MSA",points:["Categories: pass / fail","Attribute agreement","Judge with kappa ≥ 0.70"]}},{kind:"decision",say:"For a variable study, ask one question. Does the test destroy the item, or can each part only be measured by one operator? If yes, use a nested design. If no, use the normal crossed design.",title:"Crossed or nested?",question:"Destructive test, or one operator per part?",yes:"Nested Gage R&R",no:"Crossed Gage R&R"},{kind:"figure",say:"Here three evaluators classify fifteen calls against a known answer. One scores about fifty three percent, one eighty seven, one a hundred. All together agree with the standard only forty percent of the time. That is far below seventy five percent. Clarify the definition and retrain.",title:"Appraiser vs standard",figure:{kind:"interval",title:"Assessment Agreement: Appraiser vs Standard",groups:[{name:"Appraiser 1",mean:53.3,lo:26.6,hi:78.7},{name:"Appraiser 2",mean:86.7,lo:59.5,hi:98.3},{name:"Appraiser 3",mean:100,lo:81.9,hi:100},{name:"All",mean:40,lo:16.3,hi:67.7}],yLabel:"Percent agreement",note:"95% CI",refLine:75},callouts:["All vs standard 40% → not acceptable","Appraiser 1 needs targeted training","Wide intervals → use more samples"]},{kind:"callout",say:"Remember. Destructive test means nested. Categories mean attribute agreement. And kappa should be at least point seven.",big:"Destructive → nested · Kappa ≥ 0.70",small:"Variable data is always preferred"}]},{topic:"2.4.1",title:"Capability Analysis (Cp, Cpk, Pp, Ppk)",oneLine:"Capability compares the process spread and centre with the customer spec limits: Cp and Pp show potential, Cpk and Ppk show reality.",explain:["**Process capability** asks: can the process meet the customer's **specification limits** (LSL and USL)? It compares the **voice of the process** (its centre and spread) with the **voice of the customer** (the specs). It tells you if you have a **centring** problem, a **spread** problem, or both, and it gives the **baseline**.","Before capability, check three things in order: the **measurement system is OK** (MSA), the process is **stable**, and the data are **normal**. Capability uses spec limits, **never control limits**.",`**Cp** compares the spec width with the process width. It ignores where the mean is:

$$C_p = \\dfrac{USL - LSL}{6\\sigma}$$

**Cpk** uses the distance from the mean to the **nearest** spec limit, so it punishes an off-centre process:

$$C_{pk} = \\min\\left(\\dfrac{USL - \\bar{x}}{3\\sigma},\\ \\dfrac{\\bar{x} - LSL}{3\\sigma}\\right)$$`,'**Cp and Cpk** use the **short-term (within-subgroup)** sigma. **Pp and Ppk** use the same formulas with the **long-term (overall)** sigma. Long-term variation is always bigger, so Ppk is usually lower than Cpk. The book calls Cp and Pp "hope" and Cpk and Ppk "reality".',"How to decide: **Cpk ≤ Cp** always; equal only when centred. Cp much bigger than Cpk → **shift the mean** (usually the easiest fix). Cp below 1 → **reduce variation**. Cpk much bigger than Ppk → the process **shifts over time**. **Cpk ≥ 1.33** is the usual minimum; 2.0 is six sigma. With only **one** spec limit, Cp cannot be calculated."],example:`**Average handle time (AHT).** Specs: LSL = 3 min (too short = rushed calls), USL = 9 min. 100 calls: mean **6.90**, within SD **0.60**, overall SD **0.70**.

$$C_p = \\dfrac{9 - 3}{6 \\times 0.60} = 1.67 \\qquad C_{pk} = \\dfrac{9 - 6.90}{3 \\times 0.60} = 1.17$$

$$P_p = \\dfrac{9 - 3}{6 \\times 0.70} = 1.43 \\qquad P_{pk} = \\dfrac{9 - 6.90}{3 \\times 0.70} = 1.00$$

**Decision:** Cp 1.67 is good, but Cpk 1.17 is lower because the mean sits closer to the USL. This is mainly a **centring** problem: bring the mean nearer to 6 minutes. Ppk 1.00 is below Cpk, so there is extra shift over time too.`,readIt:["Check the histogram: is it inside LSL and USL? Is it centred?","Compare **Cp vs Cpk**: big gap = off-centre → shift the mean.","Cp < 1 = spread too wide for the specs → reduce variation.","Compare **Cpk vs Ppk**: big gap = process moves between subgroups over time.","Judge against **1.33**: Cpk below 1.33 is usually not good enough."],remember:["Order: MSA OK → stable → normal → capability.","Cp = spec width divided by 6σ (ignores centring).","Cpk = distance to the nearest spec divided by 3σ (real performance).","Cp, Cpk = short-term (within); Pp, Ppk = long-term (overall).","Cpk ≤ Cp; Cpk ≥ 1.33 is the usual target.","Capability uses spec limits, never control limits."],traps:["Cpk can never be bigger than Cp.","One-sided spec (e.g., only a USL) → no Cp; use the one-sided Cpk.","Using control limits in place of spec limits.","Thinking Pp/Ppk use within sigma — they use overall (long-term) sigma."],video:[{kind:"title",say:"Capability analysis. C P, C P K, P P and P P K. Can the process meet the customer specs?",title:"Process Capability",sub:"Cp · Cpk · Pp · Ppk"},{kind:"compare",say:"C P compares the spec width with the process width, and ignores where the mean is. It is the hope. C P K uses the distance to the nearest spec limit, so it shows reality. C P and C P K use short term sigma. P P and P P K use long term sigma.",title:"Hope vs reality",left:{head:"Cp / Pp = potential",points:["Spec width ÷ 6 sigma","Ignores centring","Needs both spec limits"]},right:{head:"Cpk / Ppk = actual",points:["Nearest spec ÷ 3 sigma","Punishes off-centre","Cpk ≤ Cp always"]}},{kind:"figure",say:"Here is average handle time, with specs from three to nine minutes. The spread fits well, so C P is one point six seven. But the mean is six point nine, close to the upper limit. So C P K drops to one point one seven. And P P K, using long term sigma, is one point zero. This is a centring problem.",title:"Read the capability graph",figure:{kind:"histogram",title:"Process Capability of AHT (min)",data:p,normalCurve:!0,lsl:3,usl:9,xLabel:"Minutes",stats:[["Mean","6.90"],["StDev(Within)","0.60"],["StDev(Overall)","0.70"],["Cp","1.67"],["Cpk","1.17"],["Pp","1.43"],["Ppk","1.00"]]},callouts:["Cp 1.67 but Cpk 1.17 → off-centre","Shift the mean toward 6 minutes","Ppk < Cpk → extra drift over time"]},{kind:"decision",say:"Now decide. Is C P much bigger than C P K? If yes, the process is off centre: shift the mean. That is usually the easiest fix. If no, and C P is below one, the spread is too wide: reduce variation.",title:"What to fix?",question:"Is Cp much bigger than Cpk?",yes:"Off-centre: shift the mean",no:"If Cp < 1: reduce variation"},{kind:"callout",say:"Remember. C P K is always less than or equal to C P. Aim for at least one point three three. And with only one spec limit, there is no C P.",big:"Cpk ≤ Cp · target Cpk ≥ 1.33",small:"One-sided spec → no Cp"}]},{topic:"2.4.2",title:"Concept of Stability",oneLine:"A stable process shows only common cause variation, so it is predictable over time — but stable does not mean capable.",explain:['A **stable** process is **consistent and predictable over time**. Its results still vary, but randomly around the average, with no outliers, shifts or trends. Stable is the same as **"in statistical control"**.',"There are two kinds of variation. **Common cause** variation is the normal, random noise from many small unknown factors (small day-to-day differences in call length). **Special cause** variation comes from something specific you can find: a system outage, a new untrained agent, a network change. A stable process has **only common cause** variation.","You check stability with a **time series plot** or a **control chart**. Control limits sit at **±3 sigma**, calculated **from the process data**. About **99.73%** of points fall inside by chance, so a point outside almost always means a special cause. Other signals: **9 points in a row** on one side of the centre line, or **6 in a row** going up or down.","Why it matters: capability is only meaningful on a **stable** process. If the process is unstable, today's capability does not predict tomorrow. But **stable ≠ capable**: a process can be perfectly predictable and still make defects every day, because control limits come from the process and spec limits come from the customer.","How to act: a **special cause** → investigate it, remove it and prevent it. **Only common cause** → do **not** adjust after each point (that is **tampering**, and it makes variation worse); improve the whole system instead."],example:`**Daily ticket-resolution time (hours)**, 25 days. I chart: centre line **18.14**, average moving range 1.208, so **UCL 21.36** and **LCL 14.93**.

- **Day 12 = 22.8 hours**, above the UCL. That was the day of a billing-system outage → a **special cause**. Record it and prevent a repeat; do not treat it as normal behaviour.
- All other days are inside the limits with no 9-in-a-row run → common cause only.

Even after removing the outage, the process could still miss a customer target of, say, 16 hours. Stable tells you it is **predictable**; capability tells you if it is **good enough**.`,readIt:["Any point beyond the UCL or LCL? → special cause, investigate.","Any pattern: 9 in a row on one side, 6 in a row trending? → special cause.","No signals → stable (in control): only common cause variation.","Then, separately, compare with the spec limits to judge capability."],remember:["Stable = in statistical control = only common cause variation.","Common cause = random, many small causes; special cause = specific, findable.","Control limits = ±3σ from the process data (99.73% inside).","Rules: 1 point beyond 3σ, 9 in a row one side, 6 trending.","Stable ≠ capable.","Adjusting for common cause = tampering → more variation."],traps:['"In control, so it meets customer requirements" — false: stable ≠ capable.',"Never draw spec limits on a control chart.","The exam rule for a shift is 9 points in a row, not 7 or 8."],video:[{kind:"title",say:"The concept of stability. Is the process predictable over time?",title:"Concept of Stability",sub:"Common cause vs special cause"},{kind:"compare",say:"Common cause variation is normal, random noise from many small causes. Leave it alone and improve the system. Special cause variation comes from something specific, like an outage. Find it, remove it, and stop it coming back.",title:"Two kinds of variation",left:{head:"Common cause",points:["Random noise, many small causes","Process is stable","Do not adjust point by point"]},right:{head:"Special cause",points:["Specific, findable cause","Process is unstable","Investigate and remove it"]}},{kind:"figure",say:"Here is daily ticket resolution time. The centre line is about eighteen hours. The upper control limit is about twenty one point four. Day twelve, at twenty two point eight hours, is above the limit. That was a system outage: a special cause. The other days show only common cause.",title:"Read the control chart",figure:{kind:"control",title:"I Chart of Resolution Time (hours)",panels:[{label:"Individual Value",points:u,cl:18.14,ucl:21.36,lcl:14.93,flags:[{i:11,test:"1"}],clLabel:"X̄=18.14"}],xLabel:"Day"},callouts:["Day 12 = 22.8 h, above UCL 21.36","Special cause: outage","Limits come from the process, not specs"]},{kind:"decision",say:"Stable is not the same as capable. A process can be in control and still miss the customer target every day. So ask: is it in control? Then, separately, ask: does it meet the specs?",title:"Stable is not capable",question:"In control, so it meets the specs?",yes:"Not proven: run a capability study",no:"Correct: stable ≠ capable"},{kind:"callout",say:"Remember. Stable means only common cause variation. Check it with a control chart. And stable does not mean capable.",big:"Stable ≠ capable",small:"Check stability before capability"}]},{topic:"2.4.3",title:"Attribute & Discrete Capability",oneLine:"For defect counts, turn the defect rate into DPMO, find the long-term Z, add 1.5 for short-term, and convert to Cpk and Ppk.",explain:["When the output is a **count** — dropped calls, wrong bills, errors on a form — there is no normal curve to measure, so we cannot use the Cp formula directly. Instead we turn the **defect rate** into a **Z-score** (a sigma level).",`First, know the words. A **defect** is one failed requirement. A **defective** is a whole unit that fails (it may have several defects). **DPU** = defects per unit. **DPMO** = defects per million **opportunities**, which makes processes with different complexity comparable:

$$DPMO = \\dfrac{\\text{defects}}{\\text{units} \\times \\text{opportunities}} \\times 1{,}000{,}000$$`,"Next, use the Z table **in reverse**: find the defect proportion as a tail area and read off the Z. Attribute data are collected over a long time, so this Z is **long-term** ($Z_{LT}$).",`Capability is usually reported **short-term**, so add the **1.5 sigma shift**: $Z_{ST} = Z_{LT} + 1.5$. Then:

$$C_{pk} = \\dfrac{Z_{ST}}{3} \\qquad P_{pk} = \\dfrac{Z_{LT}}{3}$$

Going the other way (short-term to long-term), you **subtract** 1.5.`,'How to judge: **Cpk ≥ 1.33** (about 4 sigma short-term) is the usual minimum. The famous "six sigma = **3.4 DPMO**" uses the **long-term** column of the sigma table.'],example:`**Book's call centre.** In one month **20,000 calls** arrived and **2,666 dropped** before being answered.

1. Proportion defective: $$p = \\dfrac{2{,}666}{20{,}000} = 0.1333$$ (about 133,300 DPMO).
2. Z table (reverse): tail 0.1333 → $Z_{LT} = 1.11$.
3. Shift: $Z_{ST} = 1.11 + 1.5 = 2.61$ → about a **2.6 sigma** process.
4. $$C_{pk} = \\dfrac{2.61}{3} = 0.87 \\qquad P_{pk} = \\dfrac{1.11}{3} = 0.37$$

**Decision:** Cpk 0.87 is far below 1.33. The process is not capable; dropped calls must be reduced.`,readIt:["Count defects, units and opportunities; compute DPU, proportion or DPMO.","Reverse Z table: defect proportion → Z long-term.","Add 1.5 → Z short-term (the sigma level usually quoted).","Cpk = Z short-term divided by 3; Ppk = Z long-term divided by 3; judge against 1.33."],remember:["Counts → DPU / DPMO → Z, not the Cp formula.","Defect = one failure; defective = whole unit fails.","Attribute data are long-term.","Z short-term = Z long-term + 1.5.","Cpk = Z short-term divided by 3; Ppk = Z long-term divided by 3.","Six sigma = 3.4 DPMO (long-term)."],traps:["Wrong direction for the shift: long-term → short-term ADD 1.5.","Forgetting opportunities: DPU and DPMO are not the same.","Treating a DPMO-based Z as short-term — attribute data are long-term."],video:[{kind:"title",say:"Attribute and discrete capability. How capable is a process that counts defects?",title:"Attribute Capability",sub:"From defect counts to a sigma level"},{kind:"formula",say:"Start with D P M O, defects per million opportunities. Divide the defects by units times opportunities, and multiply by one million. Opportunities make simple and complex processes comparable.",title:"Defects per million opportunities",name:"DPMO",num:"defects × 1,000,000",den:"units × opportunities per unit",note:"Defect = one failure · Defective = whole unit fails"},{kind:"steps",say:"Then four steps. Find the defect proportion. Use the Z table in reverse to get the long term Z. Add one point five to get the short term Z. Divide by three to get C P K. Divide the long term Z by three for P P K.",title:"From defects to Cpk",steps:["Defect proportion or DPMO","Z table in reverse → Z long-term","Add 1.5 → Z short-term","Cpk = Z ST ÷ 3, Ppk = Z LT ÷ 3"]},{kind:"bullets",say:"The book example. Twenty thousand calls, two thousand six hundred and sixty six dropped. That is about thirteen percent. Long term Z is one point one one. Short term Z is two point six one. C P K is point eight seven, far below one point three three.",title:"Dropped calls example",bullets:["2,666 of 20,000 dropped = 0.1333","Z long-term = 1.11","Z short-term = 1.11 + 1.5 = 2.61","Cpk = 0.87 → not capable"]},{kind:"callout",say:"Remember. Attribute data are long term. To get short term, add one point five. Six sigma means three point four D P M O.",big:"Z short-term = Z long-term + 1.5",small:"Six sigma = 3.4 DPMO (long-term)"}]},{topic:"2.4.4",title:"Monitoring Techniques",oneLine:"Monitor the process over time with run charts and control charts, built on rational subgroups and sensible sampling, and react only to special causes.",explain:["**Monitoring** means watching the process over time. Control charts help you set the **baseline**, check a **measurement system** (gage stability), **compare** processes, and **compare before and after** a change.","The main tools are the **time series plot** (run chart) and the **control chart**: a time plot with a centre line and **control limits at ±3 sigma** from the process data. Control limits are the voice of the process, not the customer specs.","Pick the chart by data type. Continuous data: **I-MR** for single values, **Xbar-R** for small subgroups (2–9), **Xbar-S** for subgroups of 10 or more. Pass/fail units (**defectives**): **P** or **NP**. Counts of flaws (**defects**): **U** or **C**. P and U charts handle varying sample sizes.","Collect good data. A **rational subgroup** is a few items (usually 3–5) made under the **same conditions in a short time**, so only common cause is inside it. Let the process run normally while you sample. Sample at least **10 times more often** than problems happen; start often, then reduce. Charts on outputs (Y) are **SPM** (monitoring); charts on inputs (X) are **SPC** (control).","React correctly: a **special cause** signal → investigate and prevent. **Common cause only** → do not adjust (tampering makes it worse). The chart tells you **that** something changed, not **why**."],example:`**Late order activations.** Each day 400 orders are checked; over 25 days the average proportion late is $\\bar{p} = 0.08$.

$$\\sigma_p = \\sqrt{\\dfrac{0.08 \\times 0.92}{400}} = 0.0136$$

UCL = 0.08 + 3 × 0.0136 = **0.121**; LCL = 0.08 − 3 × 0.0136 = **0.039**.

**Day 17 = 14% late**, above the UCL → special cause; the team finds a provisioning-system fault that day. A day at 11% is inside the limits → common cause, no action on its own.`,readIt:["Choose the chart: continuous vs attribute → subgroup size → defects vs defectives.","Point beyond a limit or a run rule broken → special cause, investigate.","Inside the limits, no pattern → common cause, do not adjust.","Before/after: keep the same chart running to show the change."],remember:["Control charts: baseline, gage check, compare, before/after.","Limits = mean ± 3σ from the data (voice of the process).","I-MR (n = 1), Xbar-R (2–9), Xbar-S (≥ 10), P/NP defectives, U/C defects.","Rational subgroup = 3–5 consecutive items, same conditions.","SPM = charts on Y outputs; SPC = charts on X inputs."],traps:["A subgroup taken from different machines or agents at the same moment is NOT rational.","Defectives (pass/fail units) → P/NP; defects (counts) → U/C — do not swap.","A control chart shows that a change happened, not its root cause."],video:[{kind:"title",say:"Monitoring techniques. Keep watching the process, and react only to real signals.",title:"Monitoring Techniques",sub:"Run charts and control charts"},{kind:"steps",say:"Choose the chart in order. Is the data continuous or attribute? For continuous data, look at the subgroup size: one, small, or ten plus. For attribute data, ask: is it defectives, or defects?",title:"Pick the right chart",steps:["Continuous or attribute?","n = 1 → I-MR; 2–9 → Xbar-R; ≥ 10 → Xbar-S","Defectives (pass/fail) → P or NP","Defects (counts) → U or C"]},{kind:"figure",say:"Here is a P chart of late order activations, four hundred orders a day. The average is eight percent. The upper limit is about twelve percent. Day seventeen, at fourteen percent, is above the limit. That is a special cause to investigate. The other days are common cause.",title:"P chart of late orders",figure:{kind:"control",title:"P Chart of Late Activations (n = 400)",panels:[{label:"Proportion",points:b,cl:.08,ucl:.121,lcl:.039,flags:[{i:16,test:"1"}],clLabel:"P̄=0.08"}],xLabel:"Day"},callouts:["Day 17 = 0.14, above UCL 0.121","Special cause: investigate","Other days: common cause, leave alone"]},{kind:"bullets",say:"Good data makes a good chart. Use rational subgroups: three to five items made under the same conditions. Let the process run normally. Sample often at first. And chart the inputs, not only the outputs.",title:"Collect good data",bullets:["Rational subgroup: 3–5 items, same conditions","Let the process run normally","Sample 10× more often than problems","SPC on inputs, SPM on outputs"]},{kind:"callout",say:"Remember. Special cause, investigate. Common cause, do not tamper. And control limits come from the process, never from the specs.",big:"Special cause → act · Common cause → leave it",small:"Limits come from the process, not the specs"}]},{topic:"measure-map",title:"Measure in order: from data to capability",oneLine:"First prove the measurement system, then check stability, then normality, and only then calculate capability.",explain:["Measure has a fixed order. **1) MSA OK** → **2) process stable** → **3) data normal** → **4) capability**. Each step protects the next: a bad gage makes the process look worse, an unstable process makes capability meaningless, and non-normal data make the predicted defect rate wrong.","**Which MSA?** A continuous number → **variable Gage R&R**: **crossed** normally, **nested** when the test is destructive or each part goes to one operator only. Categories (pass/fail, call type) → **attribute agreement analysis**, judged with **kappa ≥ 0.70**.","**Reading Gage R&R:** look at Total Gage R&R in the **%Study Var** column: **< 10% acceptable**, **10–30% marginal**, **> 30% unacceptable**. **ndc ≥ 5**. Part-to-part should be the largest component, and the Xbar chart by operator should be mostly **out** of control.","**Stability, then capability.** A control chart with no special-cause signals means **stable** — but **stable ≠ capable**. Capability compares with the spec limits: **Cp** is potential (ignores centring), **Cpk** is short-term reality (nearest spec), **Ppk** is long-term reality (overall sigma). usually **Ppk ≤ Cpk ≤ Cp**; target Cpk ≥ 1.33.","**Counts instead of measurements?** Use attribute capability: defects → **DPMO** → Z table in reverse → $Z_{LT}$ → $Z_{ST} = Z_{LT} + 1.5$ → $$C_{pk} = \\dfrac{Z_{ST}}{3}$$"],example:`**First-call resolution project, Measure phase.**

1. **MSA:** QA evaluators label calls "resolved / not resolved" → attribute agreement. Kappa 0.82 → OK.
2. **Stability:** P chart of daily unresolved proportion, no signals → stable.
3. **Normality:** not needed for counts — go the attribute route.
4. **Capability:** 9,000 DPMO (unresolved calls per million opportunities) → reverse Z table gives $Z_{LT} \\approx 2.37$ → $Z_{ST} \\approx 3.87$ → $C_{pk} \\approx 1.29$, just under 1.33.

Baseline set: the process is stable but **not yet capable** — the project has a clear target.`,readIt:["Gage R&R: %Study Var < 10 accept, 10–30 marginal, > 30 fix; ndc ≥ 5.","Attribute MSA: kappa ≥ 0.70; all appraisers vs standard ideally > 75–90%.","Control chart: no signals → stable; then compare with specs.","Capability: Cp vs Cpk gap → centring; Cp < 1 → spread; Cpk vs Ppk gap → drift over time."],remember:["Order: MSA → stability → normality → capability.","Destructive test → nested; categories → attribute agreement, kappa ≥ 0.70.","Gage R&R: 10% / 30% lines, ndc ≥ 5.","Cp = potential; Cpk = short-term reality; Ppk = long-term reality.","Stable ≠ capable.","Z short-term = Z long-term + 1.5."],traps:["Calculating capability before checking MSA and stability.",'Reading "in control" as "meets the specs".',"Adding 1.5 the wrong way: long-term → short-term means ADD."],video:[{kind:"title",say:"Measure in order. From raw data to capability, step by step.",title:"Measure in Order",sub:"From data to capability"},{kind:"steps",say:"Always work in this order. First, prove the measurement system with M S A. Second, check the process is stable on a control chart. Third, check the data are normal. Only then calculate capability.",title:"The Measure order",steps:["MSA OK","Process stable (control chart)","Data normal","Capability: Cp, Cpk, Pp, Ppk"]},{kind:"decision",say:"Which M S A? Is the measurement a continuous number? If yes, use Gage R and R: crossed, or nested for destructive tests. If no, people classify items, so use attribute agreement, with kappa of at least point seven.",title:"Which MSA?",question:"Is the measurement a continuous number?",yes:"Gage R&R (nested if destructive)",no:"Attribute agreement, kappa ≥ 0.70"},{kind:"bullets",say:"Reading Gage R and R. Under ten percent study variation is acceptable. Ten to thirty is marginal. Over thirty, fix the gage. And n d c should be five or more.",title:"Reading Gage R&R",bullets:["%Study Var < 10%: acceptable","10–30%: marginal","> 30%: unacceptable","ndc ≥ 5"]},{kind:"compare",say:"Then capability. C P is the potential, ignoring the centre. C P K is short term reality. P P K is long term reality, and usually the lowest. Remember, a stable process is not automatically capable.",title:"Cp vs Cpk vs Ppk",left:{head:"Potential",points:["Cp: spec width ÷ 6 sigma","Ignores centring","Stable ≠ capable"]},right:{head:"Reality",points:["Cpk: short-term, nearest spec","Ppk: long-term, overall sigma","Target Cpk ≥ 1.33"]}},{kind:"steps",say:"For counts, use attribute capability. Work out D P M O. Use the Z table in reverse for the long term Z. Add one point five for short term. Divide by three to get C P K.",title:"Counts: attribute capability",steps:["Defects → DPMO","Z table in reverse → Z long-term","Add 1.5 → Z short-term","Cpk = Z short-term ÷ 3"]},{kind:"callout",say:"Remember the order. M S A, then stable, then normal, then capability. And stable does not mean capable.",big:"MSA → stable → normal → capability",small:"Stable ≠ capable · Z ST = Z LT + 1.5"}]}],a=[...c,...f];Object.fromEntries(a.map(e=>[e.topic,e]));const g={phase:"Measure",lessons:a,base:"/measure-coach",videoDir:"videos/measure",storeKey:"svbb-coach-measure",mapTopic:"measure-map",mapSection:"2.4",mapPool:e=>e.phase===2&&(e.topic.startsWith("2.3")||e.topic.startsWith("2.4"))&&(e.qtype==="best-action"||e.qtype==="scenario"||e.qtype==="output"),theme:{text:"text-teal",bg:"bg-teal",soft:"bg-teal/10",softer:"bg-teal/5"}};function R(){return s.jsx(i,{cfg:g})}export{R as default};
